const item = $input.first();
const raw = item.json || {};

const text = (value, fallback = '') => value === undefined || value === null ? fallback : String(value).trim();
const obj = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const list = (value) => Array.isArray(value) ? value : [];

function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  if (value && typeof value === 'object') {
    return Object.keys(value).sort().reduce((acc, key) => {
      acc[key] = canonical(value[key]);
      return acc;
    }, {});
  }
  return value;
}

function hash(value) {
  const source = JSON.stringify(canonical(value));
  let result = 2166136261;
  for (let index = 0; index < source.length; index++) {
    result ^= source.charCodeAt(index);
    result = Math.imul(result, 16777619);
  }
  return (result >>> 0).toString(16).padStart(8, '0');
}

function redact(value) {
  return text(value)
    .replace(/Bearer\s+[A-Za-z0-9._~+\/=-]+/gi, 'Bearer [REDACTED]')
    .replace(/\bsk-[A-Za-z0-9_-]{12,}\b/g, '[API_KEY_REDACTED]')
    .replace(/\b(api[_-]?key|token|secret|password)\s*[:=]\s*["']?[^,\s"']+/gi, '$1=[REDACTED]')
    .replace(/\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/g, '[JWT_REDACTED]')
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL_REDACTED]')
    .replace(/(?:\+?55\s*)?(?:\(?\d{2}\)?\s*)?(?:9?\d{4})[-.\s]?\d{4}/g, '[PHONE_REDACTED]')
    .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, '[CPF_REDACTED]');
}

function normalizeMessage(value) {
  return redact(value)
    .toLowerCase()
    .replace(/\b\d{4,}\b/g, '#')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 1000);
}

const envelope = obj(raw.error_event || raw.incident || raw);
const execution = obj(envelope.execution || raw.execution);
const workflow = obj(envelope.workflow || raw.workflow);
const error = obj(execution.error || envelope.error || raw.error);
const node = obj(error.node || envelope.node);
const context = obj(
  envelope.recovery_context ||
  envelope.context ||
  raw.recovery_context ||
  raw.context
);
const policy = obj(context.recovery_policy || raw.recovery_policy);

const workflowName = text(workflow.name || context.workflow_name || raw.workflow_name, 'Unknown workflow');
const workflowId = text(workflow.id || context.workflow_id || raw.workflow_id);
const executionId = text(execution.id || context.execution_id || raw.execution_id);
const executionUrl = text(execution.url || context.execution_url || raw.execution_url);
const nodeName = text(
  execution.lastNodeExecuted ||
  node.name ||
  context.node_name ||
  raw.node_name,
  'Unknown node'
);
const errorName = text(error.name || error.type || context.error_name, 'Error');
const message = redact(error.message || envelope.message || raw.message || 'Unknown error');
const stack = redact(error.stack || envelope.stack || raw.stack).slice(0, 8000);
const statusCode = Number(
  error.httpCode ||
  error.statusCode ||
  error.status ||
  envelope.status_code ||
  raw.status_code ||
  0
);
const errorCode = text(
  error.code ||
  error.errorCode ||
  envelope.error_code ||
  raw.error_code
).toUpperCase();

const combined = `${workflowName} ${nodeName} ${errorName} ${message}`;
const moduleMatch = combined.match(/\bCCG[-_ ]?(00|10|20|30|40|50|60|70|80|90|99)\b/i);
const explicitModule = text(context.module || raw.ccg_module).toUpperCase();
const moduleName = /^CCG-(?:00|10|20|30|40|50|60|70|80|90|99)$/.test(explicitModule)
  ? explicitModule
  : moduleMatch
    ? `CCG-${moduleMatch[1]}`
    : 'UNKNOWN';

const jobMatch = combined.match(/\b(?:job[_ -]?id|job)\s*[:=]\s*([A-Za-z0-9_.:-]+)/i);
const productionExecution = obj(raw.production_execution_results || raw.data?.production_execution_results || envelope.production_execution_results || raw.execution_results);
const executorHandoff = obj(raw.executor_handoff || raw.data?.executor_handoff || envelope.executor_handoff);
const executorCheckpoint = obj(productionExecution.checkpoint || executorHandoff.checkpoint || context.checkpoint);
const productionJobId = text(context.failed_job_id || productionExecution.failed_job_id || productionExecution.failed_job?.job_id || executorHandoff.failed_job_id);
const executionJobEvidence = list(productionExecution.jobs || productionExecution.results).find((job) => text(job?.job_id) === productionJobId) || {};
const providerJobId = text(productionExecution.provider_job_id || productionExecution.failed_job?.provider_job_id || executionJobEvidence.provider_job_id || executorHandoff.provider_job_id);
const executorExecutionId = text(productionExecution.execution_id || executorHandoff.execution_id || executorCheckpoint.execution_id);
const failedJobId = text(
  productionJobId ||
  context.failed_job_id ||
  envelope.failed_job_id ||
  raw.failed_job_id ||
  (jobMatch ? jobMatch[1] : '')
);

const tier = text(context.production_tier || raw.production_request?.production_tier, 'STANDARD').toUpperCase();
const tierAttempts = { FAST: 2, STANDARD: 3, PREMIUM: 4 };
const currentAttempt = Math.max(
  1,
  Number(
    context.current_attempt ||
    envelope.current_attempt ||
    raw.current_attempt ||
    (execution.retryOf ? 2 : 1)
  )
);
const maxAttempts = Math.max(
  1,
  Number(
    context.max_attempts ||
    policy.max_attempts ||
    tierAttempts[tier] ||
    3
  )
);

const normalizedForFingerprint = normalizeMessage(message);
const fingerprint = hash({
  workflow_id: workflowId || workflowName,
  node_name: nodeName,
  error_name: errorName,
  error_code: errorCode,
  status_code: statusCode,
  normalized_message: normalizedForFingerprint
});
const incidentId = `INC-${fingerprint}-${executionId || 'untracked'}`;
const runId = text(
  context.run_id ||
  raw.ccg_context?.run_id ||
  raw.run_id,
  `error-run-${fingerprint}`
);
const idempotencyKey = text(
  context.idempotency_key ||
  raw.ccg_context?.idempotency_key ||
  raw.idempotency_key,
  `ccg:error:${fingerprint}`
);

const normalized = {
  incident_version: '1.0.0',
  incident_id: incidentId,
  fingerprint,
  deduplication_key: `ccg:error:${fingerprint}`,
  detected_at: new Date().toISOString(),
  source: {
    trigger_type: execution.id || workflow.id ? 'N8N_ERROR_TRIGGER' : 'SUBWORKFLOW_ERROR_EVENT',
    workflow_id: workflowId,
    workflow_name: workflowName,
    execution_id: executionId,
    execution_url: executionUrl,
    execution_mode: text(execution.mode),
    retry_of_execution_id: text(execution.retryOf),
    node_name: nodeName,
    node_type: text(node.type),
    module: moduleName,
    failed_job_id: failedJobId,
    provider_job_id: providerJobId,
    executor_execution_id: executorExecutionId,
    execution_status: text(productionExecution.status),
    checkpoint_id: text(executorCheckpoint.execution_id || context.checkpoint_id)
  },
  error: {
    name: errorName,
    code: errorCode,
    status_code: statusCode,
    message,
    normalized_message: normalizedForFingerprint,
    stack,
    stack_fingerprint: hash(stack || message)
  },
  ccg_context: {
    run_id: runId,
    idempotency_key: idempotencyKey,
    production_id: text(context.production_id || raw.production_request?.production_id),
    campaign_id: text(context.campaign_id || raw.production_request?.campaign_id),
    content_id: text(context.content_id || raw.production_request?.content_id),
    production_tier: tier,
    mode: text(context.mode || raw.ccg_context?.mode || (raw.production_request?.dry_run === true ? 'DRY_RUN' : 'LIVE'))
  },
  recovery_context: {
    current_attempt: currentAttempt,
    max_attempts: maxAttempts,
    checkpoint_module: text(context.checkpoint_module, moduleName),
    previous_checkpoint_id: text(context.checkpoint_id || executorCheckpoint.execution_id),
    checkpoint_id: text(executorCheckpoint.execution_id || context.checkpoint_id),
    executor_execution_id: executorExecutionId,
    provider_job_id: providerJobId,
    failed_job_id: failedJobId,
    executor_checkpoint: executorCheckpoint,
    production_execution_results: productionExecution,
    adapter_workflow_id: text(context.adapter_workflow_id),
    dispatcher_workflow_id: text(policy.dispatcher_workflow_id || context.dispatcher_workflow_id),
    policy: {
      dispatch_enabled: policy.dispatch_enabled === true,
      allow_execution_retry: policy.allow_execution_retry !== false,
      allow_checkpoint_resume: policy.allow_checkpoint_resume !== false,
      maximum_backoff_seconds: Math.max(30, Number(policy.maximum_backoff_seconds || 900)),
      notify_severities: list(policy.notify_severities).length
        ? list(policy.notify_severities).map((value) => text(value).toUpperCase())
        : ['HIGH', 'CRITICAL']
    }
  },
  raw_evidence: {
    execution_started_at: text(execution.startedAt),
    execution_stopped_at: text(execution.stoppedAt),
    input_has_binary: Boolean(item.binary && Object.keys(item.binary).length),
    executor_execution_id: executorExecutionId,
    checkpoint_id: text(executorCheckpoint.execution_id),
    provider_job_id: providerJobId
  }
};

return [{
  json: {
    normalized_error_event: normalized
  },
  binary: item.binary
}];

const item = $input.first();
const event = item.json?.normalized_error_event || {};

const text = (value, fallback = '') => value === undefined || value === null ? fallback : String(value).trim();
const list = (value) => Array.isArray(value) ? value : [];
const unique = (values) => [...new Set(values.map((value) => text(value)).filter(Boolean))];

const source = event.source || {};
const error = event.error || {};
const recovery = event.recovery_context || {};
const message = `${text(error.name)} ${text(error.code)} ${Number(error.status_code || 0)} ${text(error.normalized_message)}`.toLowerCase();
const statusCode = Number(error.status_code || 0);

const rules = [
  {
    category: 'RATE_LIMIT',
    retryable: true,
    severity: 'MEDIUM',
    patterns: [/\b429\b/, /rate[_ -]?limit/, /executor.*429/, /too many requests/, /throttl/]
  },
  {
    category: 'TRANSIENT_NETWORK',
    retryable: true,
    severity: 'MEDIUM',
    patterns: [/etimedout/, /econnreset/, /eai_again/, /socket hang up/, /network error/, /temporary failure/, /connection reset/]
  },
  {
    category: 'PROVIDER_TIMEOUT',
    retryable: true,
    severity: 'MEDIUM',
    patterns: [/timeout/, /timed out/, /deadline exceeded/, /gateway timeout/]
  },
  {
    category: 'PROVIDER_5XX',
    retryable: true,
    severity: 'HIGH',
    patterns: [/\b50[0234]\b/, /bad gateway/, /service unavailable/, /internal server error/, /provider 5\d\d/]
  },
  {
    category: 'AUTHENTICATION',
    retryable: false,
    severity: 'HIGH',
    patterns: [/\b401\b/, /\b403\b/, /unauthoriz/, /forbidden/, /invalid api key/, /authentication error/, /not logged in/]
  },
  {
    category: 'MISSING_CREDENTIAL',
    retryable: false,
    severity: 'HIGH',
    patterns: [/missing credential/, /credential.*not found/, /no credentials?/, /missing api key/, /credential reference/]
  },
  {
    category: 'BUDGET_OR_QUOTA',
    retryable: false,
    severity: 'HIGH',
    patterns: [/budget exceeded/, /max(?:imum)? cost/, /insufficient quota/, /billing/, /credit balance/, /cost not recorded/]
  },
  {
    category: 'RIGHTS_CONSENT_POLICY',
    retryable: false,
    severity: 'CRITICAL',
    patterns: [/rights? block/, /license.*(?:fail|missing|restricted)/, /consent.*(?:required|missing|invalid)/, /patient/, /personal data/, /policy block/, /publication.*forbidden/, /publish_allowed=true/]
  },
  {
    category: 'VALIDATION_OR_CONTRACT',
    retryable: false,
    severity: 'HIGH',
    patterns: [/\[ccg-\d+\/input\]/, /validation/, /invalid input/, /schema/, /contract/, /malformed json/, /parser/, /structured output/, /required field/]
  },
  {
    category: 'DEPENDENCY_OR_DAG',
    retryable: false,
    severity: 'HIGH',
    patterns: [/missing dependency/, /dependency cycle/, /unknown .*job/, /no provider for capability/, /missing adapter workflow/, /unknown_tts_job/, /unknown_music_job/, /final_output_count_mismatch/]
  },
  {
    category: 'MISSING_EXECUTION_EVIDENCE',
    retryable: false,
    severity: 'HIGH',
    patterns: [/awaiting execution/, /missing job result/, /missing artifact/, /missing provider receipt/, /checksum/, /artifact.*(?:absent|missing|diverg)/, /execution results?/]
  },
  {
    category: 'STORAGE_OR_RUNTIME',
    retryable: false,
    severity: 'HIGH',
    patterns: [/enospc/, /no space left/, /out of memory/, /heap out of memory/, /permission denied/, /read-only file system/]
  },
  {
    category: 'MANUAL_CANCELLATION',
    retryable: false,
    severity: 'LOW',
    patterns: [/cancelled by user/, /canceled by user/, /execution cancelled/, /execution canceled/, /manually stopped/]
  }
];

let classification = null;
for (const rule of rules) {
  if (rule.patterns.some((pattern) => pattern.test(message))) {
    classification = {
      category: rule.category,
      retryable: rule.retryable,
      severity: rule.severity,
      matched_signals: rule.patterns
        .filter((pattern) => pattern.test(message))
        .map((pattern) => pattern.source)
    };
    break;
  }
}

if (!classification && statusCode >= 500 && statusCode <= 599) {
  classification = {
    category: 'PROVIDER_5XX',
    retryable: true,
    severity: 'HIGH',
    matched_signals: [`HTTP_${statusCode}`]
  };
}

if (!classification) {
  classification = {
    category: 'UNKNOWN',
    retryable: false,
    severity: 'HIGH',
    matched_signals: []
  };
}

const moduleOrder = ['CCG-00', 'CCG-10', 'CCG-20', 'CCG-30', 'CCG-40', 'CCG-50', 'CCG-60', 'CCG-70', 'CCG-80', 'CCG-90'];
const moduleIndex = moduleOrder.indexOf(text(source.module));
const preserveModules = moduleIndex > 0 ? moduleOrder.slice(0, moduleIndex) : [];
const invalidateModules = moduleIndex >= 0 ? moduleOrder.slice(moduleIndex) : [];

const currentAttempt = Number(recovery.current_attempt || 1);
const maxAttempts = Number(recovery.max_attempts || 3);
const attemptsRemaining = Math.max(0, maxAttempts - currentAttempt);
const retryPermitted = (
  classification.retryable &&
  attemptsRemaining > 0 &&
  recovery.policy?.allow_execution_retry !== false
);

let action = 'HOLD_FOR_REVIEW';
let resumeModule = text(recovery.checkpoint_module, text(source.module, 'CCG-00'));
let reason = 'Falha não deve ser repetida automaticamente.';

if (classification.category === 'MANUAL_CANCELLATION') {
  action = 'TERMINATE';
  reason = 'Execução interrompida manualmente.';
} else if (
  classification.category === 'MISSING_EXECUTION_EVIDENCE' &&
  recovery.policy?.allow_checkpoint_resume !== false
) {
  action = 'RESUME_FROM_CHECKPOINT';
  resumeModule = ['CCG-80', 'CCG-90'].includes(text(source.module))
    ? 'CCG-80-EXECUTION'
    : resumeModule;
  reason = 'A produção possui planejamento, mas faltam resultados ou evidências de execução.';
} else if (retryPermitted) {
  action = 'RETRY_FAILED_EXECUTION';
  reason = 'Falha transitória classificada como segura para nova tentativa idempotente.';
} else if (classification.retryable && !attemptsRemaining) {
  action = 'HOLD_FOR_REVIEW';
  reason = 'Limite de tentativas atingido.';
}

const backoffTable = [30, 120, 300, 900, 1800];
const proposedBackoff = backoffTable[Math.min(currentAttempt - 1, backoffTable.length - 1)];
const backoffSeconds = Math.min(
  proposedBackoff,
  Number(recovery.policy?.maximum_backoff_seconds || 900)
);

const highImpactModule = ['CCG-80', 'CCG-90'].includes(text(source.module));
if (highImpactModule && classification.severity === 'MEDIUM') {
  classification.severity = 'HIGH';
}

const decision = {
  classification_version: '1.0.0',
  category: classification.category,
  severity: classification.severity,
  retryable: classification.retryable,
  confidence: classification.category === 'UNKNOWN' ? 0.35 : 0.92,
  matched_signals: unique(classification.matched_signals),
  action,
  action_reason: reason,
  attempts: {
    current: currentAttempt,
    maximum: maxAttempts,
    remaining: attemptsRemaining,
    next_attempt: action === 'RETRY_FAILED_EXECUTION' ? currentAttempt + 1 : currentAttempt
  },
  timing: {
    backoff_seconds: action === 'RETRY_FAILED_EXECUTION' ? backoffSeconds : 0,
    not_before: action === 'RETRY_FAILED_EXECUTION'
      ? new Date(Date.now() + backoffSeconds * 1000).toISOString()
      : ''
  },
  recovery_scope: {
    resume_module: resumeModule,
    failed_job_id: text(source.failed_job_id || recovery.failed_job_id),
    provider_job_id: text(source.provider_job_id || recovery.provider_job_id),
    executor_execution_id: text(source.executor_execution_id || recovery.executor_execution_id),
    checkpoint_id: text(source.checkpoint_id || recovery.checkpoint_id),
    retry_scope: text(source.failed_job_id || recovery.failed_job_id)
      ? 'FAILED_JOB'
      : text(source.execution_id)
        ? 'FAILED_EXECUTION'
        : 'FAILED_MODULE'
  },
  containment: {
    freeze_downstream: true,
    preserve_upstream_modules: preserveModules,
    invalidate_modules: invalidateModules,
    cancel_open_provider_jobs: ['RIGHTS_CONSENT_POLICY', 'BUDGET_OR_QUOTA'].includes(classification.category),
    preserve_evidence: true,
    publication_gate_closed: true
  },
  human_review: {
    required: action !== 'RETRY_FAILED_EXECUTION',
    priority: classification.severity,
    reasons: action === 'RETRY_FAILED_EXECUTION'
      ? []
      : [reason, `Categoria: ${classification.category}`]
  }
};

return [{
  json: {
    normalized_error_event: event,
    recovery_decision: decision
  },
  binary: item.binary
}];

const item = $input.first();
const event = item.json.normalized_error_event || {};
const decision = item.json.recovery_decision || {};
const source = event.source || {};
const context = event.ccg_context || {};
const recovery = event.recovery_context || {};

const target = decision.recovery_scope?.retry_scope === 'FAILED_JOB'
  ? {
      target_type: 'JOB',
      target_id: decision.recovery_scope.failed_job_id,
      operation: 'RETRY_JOB_FROM_ADAPTER'
    }
  : source.execution_id
    ? {
        target_type: 'N8N_EXECUTION',
        target_id: source.execution_id,
        operation: 'RETRY_FAILED_EXECUTION'
      }
    : {
        target_type: 'CCG_MODULE',
        target_id: source.module,
        operation: 'REEXECUTE_MODULE'
      };

return [{
  json: {
    ...item.json,
    recovery_handoff: {
      action: 'RETRY_FAILED_EXECUTION',
      status: 'RETRY_PLANNED',
      target,
      not_before: decision.timing?.not_before,
      backoff_seconds: decision.timing?.backoff_seconds,
      attempt: decision.attempts?.next_attempt,
      maximum_attempts: decision.attempts?.maximum,
      failed_job_id: decision.recovery_scope?.failed_job_id || recovery.failed_job_id || '',
      provider_job_id: decision.recovery_scope?.provider_job_id || recovery.provider_job_id || '',
      executor_execution_id: decision.recovery_scope?.executor_execution_id || recovery.executor_execution_id || '',
      checkpoint_id: decision.recovery_scope?.checkpoint_id || recovery.checkpoint_id || '',
      resume_module: decision.recovery_scope?.resume_module,
      idempotency_key: `${context.idempotency_key}:retry:${decision.attempts?.next_attempt}`,
      executor_checkpoint: {
        execution_id: recovery.executor_execution_id || '',
        checkpoint_id: recovery.checkpoint_id || '',
        failed_job_id: recovery.failed_job_id || '',
        provider_job_id: recovery.provider_job_id || ''
      },
      dispatcher_contract: {
        dispatch_enabled: recovery.policy?.dispatch_enabled === true,
        dispatcher_workflow_id: recovery.dispatcher_workflow_id || '',
        adapter_workflow_id: recovery.adapter_workflow_id || '',
        dispatched_by_this_workflow: false,
        require_idempotency: true,
        require_original_input_snapshot: true,
        require_previous_execution_reference: Boolean(source.execution_id)
      },
      operator_instruction: `Executar nova tentativa somente após ${decision.timing?.backoff_seconds || 0}s, preservando a mesma chave de produção.`
    }
  },
  binary: item.binary
}];

const item = $input.first();
const event = item.json.normalized_error_event || {};
const decision = item.json.recovery_decision || {};
const context = event.ccg_context || {};
const recovery = event.recovery_context || {};

return [{
  json: {
    ...item.json,
    recovery_handoff: {
      action: 'RESUME_FROM_CHECKPOINT',
      status: 'RESUME_REQUIRED',
      target: {
        target_type: 'CHECKPOINT',
        target_id: decision.recovery_scope?.resume_module,
        operation: 'RESUME_PIPELINE'
      },
      resume_module: decision.recovery_scope?.resume_module,
      failed_job_id: decision.recovery_scope?.failed_job_id || '',
      previous_checkpoint_id: recovery.previous_checkpoint_id || recovery.checkpoint_id || '',
      executor_execution_id: recovery.executor_execution_id || '',
      provider_job_id: recovery.provider_job_id || '',
      executor_checkpoint: recovery.executor_checkpoint || {},
      idempotency_key: `${context.idempotency_key}:resume:${decision.recovery_scope?.resume_module}`,
      required_inputs: [
        'last_valid_module_output',
        'production_manifest',
        'production_execution_results_or_executor_checkpoint',
        'execution_results_or_adapter_receipts',
        'original_ccg_context'
      ],
      dispatcher_contract: {
        dispatch_enabled: recovery.policy?.dispatch_enabled === true,
        dispatcher_workflow_id: recovery.dispatcher_workflow_id || '',
        dispatched_by_this_workflow: false,
        require_idempotency: true
      },
      operator_instruction: `Retomar a partir de ${decision.recovery_scope?.resume_module}, sem repetir módulos já válidos.`
    }
  },
  binary: item.binary
}];

const item = $input.first();
const event = item.json.normalized_error_event || {};
const decision = item.json.recovery_decision || {};
const source = event.source || {};
const error = event.error || {};
const context = event.ccg_context || {};

return [{
  json: {
    ...item.json,
    recovery_handoff: {
      action: 'HOLD_FOR_REVIEW',
      status: 'HELD_FOR_REVIEW',
      target: {
        target_type: 'REVIEW_QUEUE',
        target_id: decision.severity,
        operation: 'CREATE_OR_UPDATE_INCIDENT'
      },
      idempotency_key: `${context.idempotency_key}:review:${event.fingerprint}`,
      review_packet: {
        incident_id: event.incident_id,
        severity: decision.severity,
        category: decision.category,
        module: source.module,
        node_name: source.node_name,
        failed_job_id: source.failed_job_id,
        execution_id: source.execution_id,
        execution_url: source.execution_url,
        error_name: error.name,
        error_code: error.code,
        status_code: error.status_code,
        message: error.message,
        attempt: decision.attempts?.current,
        maximum_attempts: decision.attempts?.maximum,
        containment: decision.containment,
        suggested_checks: [
          'Confirmar se o input e o contrato do módulo continuam válidos.',
          'Verificar credencial, capability, adapter e provider policy.',
          'Verificar orçamento, direitos, licenças e consentimentos.',
          'Preservar outputs válidos e não liberar publicação.',
          'Registrar correção antes de autorizar nova tentativa.'
        ]
      },
      operator_instruction: 'Corrigir a causa comprovada e somente então escolher entre retomar, repetir ou encerrar.'
    }
  },
  binary: item.binary
}];

const item = $input.first();
const event = item.json.normalized_error_event || {};
const decision = item.json.recovery_decision || {};
const context = event.ccg_context || {};

return [{
  json: {
    ...item.json,
    recovery_handoff: {
      action: 'TERMINATE',
      status: 'TERMINATED',
      target: {
        target_type: 'PIPELINE',
        target_id: context.run_id,
        operation: 'CLOSE_WITHOUT_RETRY'
      },
      idempotency_key: `${context.idempotency_key}:terminate:${event.fingerprint}`,
      close_reason: decision.action_reason,
      preserve_evidence: true,
      cancel_downstream: true,
      operator_instruction: 'Encerrar a execução sem nova tentativa e manter o incidente no ledger.'
    }
  },
  binary: item.binary
}];

const item = $input.first();
const event = item.json.normalized_error_event || {};
const decision = item.json.recovery_decision || {};
const handoff = item.json.recovery_handoff || {};
const source = event.source || {};
const error = event.error || {};
const context = event.ccg_context || {};
const now = new Date().toISOString();

const text = (value, fallback = '') => value === undefined || value === null ? fallback : String(value).trim();
const list = (value) => Array.isArray(value) ? value : [];
const unique = (values) => [...new Set(values.map((value) => text(value)).filter(Boolean))];

const incidentStatus = handoff.status || 'HELD_FOR_REVIEW';
const nextModule = handoff.action === 'RETRY_FAILED_EXECUTION'
  ? 'CCG-99-RETRY'
  : handoff.action === 'RESUME_FROM_CHECKPOINT'
    ? handoff.resume_module || 'CCG-REVIEW'
    : handoff.action === 'TERMINATE'
      ? 'CCG-99-CLOSED'
      : 'CCG-REVIEW';

const notificationEnabled = list(event.recovery_context?.policy?.notify_severities)
  .includes(text(decision.severity).toUpperCase());

const incidentReport = {
  incident_version: '1.0.0',
  incident_id: event.incident_id,
  fingerprint: event.fingerprint,
  deduplication_key: event.deduplication_key,
  status: incidentStatus,
  severity: decision.severity,
  category: decision.category,
  detected_at: event.detected_at,
  handled_at: now,
  source,
  error: {
    name: error.name,
    code: error.code,
    status_code: error.status_code,
    message: error.message,
    stack_fingerprint: error.stack_fingerprint
  },
  context: {
    run_id: context.run_id,
    idempotency_key: context.idempotency_key,
    production_id: context.production_id,
    campaign_id: context.campaign_id,
    content_id: context.content_id,
    mode: context.mode,
    production_tier: context.production_tier
  },
  classification: {
    retryable: decision.retryable,
    confidence: decision.confidence,
    matched_signals: unique(list(decision.matched_signals))
  },
  attempts: decision.attempts,
  containment: decision.containment,
  recovery_handoff: handoff,
  human_review: decision.human_review,
  next_module: nextModule,
  publication_gate: {
    publish_requested: false,
    publish_allowed: false,
    published: false,
    automatic_publication_forbidden: true
  },
  evidence: {
    execution_url: source.execution_url,
    execution_id: source.execution_id,
    stack_fingerprint: error.stack_fingerprint,
    input_has_binary: event.raw_evidence?.input_has_binary === true,
    executor_execution_id: text(event.source?.executor_execution_id || event.recovery_context?.executor_execution_id),
    checkpoint_id: text(event.source?.checkpoint_id || event.recovery_context?.checkpoint_id),
    provider_job_id: text(event.source?.provider_job_id || event.recovery_context?.provider_job_id),
    failed_job_id: text(event.source?.failed_job_id || event.recovery_context?.failed_job_id)
  }
};

const ledgerEvent = {
  event_name: 'ccg.incident.handled',
  event_version: '1.0.0',
  event_id: `${event.incident_id}:${incidentStatus.toLowerCase()}`,
  occurred_at: now,
  idempotency_key: `${context.idempotency_key}:CCG-99:${event.fingerprint}`,
  payload: {
    incident_id: event.incident_id,
    fingerprint: event.fingerprint,
    run_id: context.run_id,
    module: source.module,
    node_name: source.node_name,
    failed_job_id: source.failed_job_id,
    category: decision.category,
    severity: decision.severity,
    action: handoff.action,
    status: incidentStatus,
    next_module: nextModule,
    attempt: decision.attempts?.current,
    next_attempt: decision.attempts?.next_attempt,
    executor_execution_id: text(event.recovery_context?.executor_execution_id),
    checkpoint_id: text(event.recovery_context?.checkpoint_id),
    provider_job_id: text(event.recovery_context?.provider_job_id)
  }
};

return [{
  json: {
    ccg_module: 'CCG-99',
    module_status: 'DONE',
    module_output: 'incident_report',
    output_type: 'ERROR_HANDLER_RESULT',
    status: incidentStatus,
    next_module: nextModule,
    incident_report: incidentReport,
    ledger_events: [ledgerEvent],
    notification_payload: {
      enabled: notificationEnabled,
      severity: decision.severity,
      title: `[${decision.severity}] ${decision.category} em ${source.module}`,
      summary: `${source.workflow_name} / ${source.node_name}: ${error.message}`,
      incident_id: event.incident_id,
      execution_url: source.execution_url,
      tags: unique([
        'campaign-creative-generator',
        source.module,
        decision.category,
        decision.severity
      ])
    },
    recovery_dispatch: {
      requested: event.recovery_context?.policy?.dispatch_enabled === true,
      dispatcher_workflow_id: event.recovery_context?.dispatcher_workflow_id || '',
      dispatched_by_this_workflow: false,
      handoff
    },
    posting_payload: {
      publish_requested: false,
      publish_allowed: false,
      published: false
    },
    archive_policy: {
      archive_ready: incidentStatus === 'TERMINATED',
      reason: incidentStatus === 'TERMINATED'
        ? 'Incidente encerrado sem retry.'
        : 'Incidente exige retry, retomada ou revisão antes do arquivamento.'
    }
  },
  binary: item.binary
}];

const item = $input.first();
const data = item.json || {};
const report = data.incident_report;

if (!report || !report.incident_id) {
  throw new Error('[CCG-99/OUTPUT] incident_report não foi produzido.');
}

return [{
  json: {
    ...data,
    module_result: {
      module: 'CCG-99',
      status: 'DONE',
      output_type: 'INCIDENT_REPORT',
      incident_id: report.incident_id,
      incident_status: report.status,
      severity: report.severity,
      category: report.category,
      action: report.recovery_handoff?.action,
      next_module: report.next_module,
      fingerprint: report.fingerprint
    },
    safety: {
      publication_closed: true,
      automatic_retry_executed: false,
      recovery_dispatched: false,
      evidence_preserved: true
    },
    error_handling: 'native-error-trigger-and-subworkflow-contract'
  },
  binary: item.binary
}];
